#include <stdio.h>
#include "Foo.h"  // Include the file generated by ASN1C 
#include "rtxsrc/rtxStreamFile.h"
#include "rtxsrc/rtxMemLeakCheck.h"

int main() {
  OSOCTET msgbuf[1024];       // Buffer to hold the encoded message
  //ASN1TAG msgtag;             // Tag for the message
  int msglen;                 // Length of the message
  OSCTXT ctxt;                // Context for decoding
  S1 decoded_data; // The decoded data (MyType corresponds to your ASN.1 type)
  int status;
  OSBOOL aligned = FALSE;

  DECLARE_MEMLEAK_DETECTOR;
  
  // Read the message from stdin into msgbuf
  msglen = fread(msgbuf, 1, sizeof(msgbuf), stdin);
  if (msglen <= 0) {
    printf("Error reading input\n");
    return -1;
  }

  // Step 1: Initialize the context for decoding
  if (rtInitContext(&ctxt) != 0) {
    printf("Context initialization failed (check license)\n");
    return -1;
  }

  // Step 2: Set the context with the message buffer
  pu_setBuffer(&ctxt, msgbuf, msglen, aligned);

  // Step 3: Call the module's initialization functions
  // asn1Init_S1(&decoded_data);

  // Step 4: Decode the input using UPER
  status = asn1PD_S1(&ctxt, &decoded_data);
  if (status != 0) {
    printf("Error decoding the message: %d\n", status);
    return -1;
  }


  // Encode the data back to JER format

  OSCTXT ctxt_json;
  if (rtInitContext(&ctxt_json) != 0) {
    // initialization failed, could be a license problem 
    printf("context initialization failed (check license)\n");
    return -1;
  }

  int stat = rtInitContext(&ctxt_json);

  rtxCtxtSetFlag(&ctxt_json, OSNOWHITESPACE);
  stat =  rtxStreamFileAttach(&ctxt_json, stdout, OSRTSTRMF_OUTPUT);
  if (stat != 0) {
    printf("Unable to create file stream.\n");
    rtxErrPrint(&ctxt_json);
    return stat;
  }
  //rtxSetDiag (&ctxt, verbose);

  // populate  structure

  stat = asn1JsonEnc_S1(&ctxt_json, &decoded_data);
    
  // Step 7: Output the encoded JER data
 
  // Step 8: Free dynamically allocated memory (if any)

  rtFreeContext(&ctxt_json); 

  rtFreeContext(&ctxt);
  return 0; 
}

